 length: { mm:{name:"Millimeter",f:0.001}, cm:{name:"Centimeter",f:0.01}, m:{name:"Meter",f:1}, km:{name:"Kilometer",f:1000}, in:{name:"Inch",f:0.0254}, ft:{name:"Foot",f:0.3048}, yd:{name:"Yard",f:0.9144}, mi:{name:"Mile",f:1609.344}, nmi:{name:"Nautical mile",f:1852} },
