 area: { mm2:{name:"mm²",f:1e-6}, cm2:{name:"cm²",f:1e-4}, m2:{name:"m²",f:1}, km2:{name:"km²",f:1e6}, in2:{name:"in²",f:0.00064516}, ft2:{name:"ft²",f:0.09290304}, yd2:{name:"yd²",f:0.83612736}, acre:{name:"Acre",f:4046.8564224}, hectare:{name:"Hectare",f:10000} },
 volume: { ml:{name:"Milliliter",f:0.001}, l:{name:"Liter",f:1}, m3:{name:"Cubic meter",f:1000}, tsp:{name:"Teaspoon",f:0.00492892159}, tbsp:{name:"Tablespoon",f:0.0147867648}, cup:{name:"Cup",f:0.2365882365}, pint:{name:"Pint",f:0.473176473}, quart:{name:"Quart",f:0.946352946}, gallon:{name:"US gallon",f:3.785411784} },
 time: { ms:{name:"Millisecond",f:0.001}, s:{name:"Second",f:1}, min:{name:"Minute",f:60}, h:{name:"Hour",f:3600}, d:{name:"Day",f:86400}, week:{name:"Week",f:604800}, month:{name:"30-day month",f:2592000}, year:{name:"365-day year",f:31536000} },
 speed: { ms:{name:"m/s",f:1}, kmh:{name:"km/h",f:1000/3600}, mph:{name:"mph",f:1609.344/3600}, knot:{name:"Knot",f:1852/3600} },
 data: { bit:{name:"Bit",f:1/8}, byte:{name:"Byte",f:1}, kb:{name:"KB",f:1024}, mb:{name:"MB",f:1024**2}, gb:{name:"GB",f:1024**3}, tb:{name:"TB",f:1024**4} },
 pressure: { pa:{name:"Pa",f:1}, kpa:{name:"kPa",f:1000}, bar:{name:"Bar",f:100000}, psi:{name:"PSI",f:6894.757293}, atm:{name:"Atmosphere",f:101325} },
 energy: { j:{name:"Joule",f:1}, kj:{name:"Kilojoule",f:1000}, cal:{name:"Calorie",f:4.184}, kcal:{name:"Kilocalorie",f:4184}, kwh:{name:"kWh",f:3600000} },
